import React, { useEffect, useState } from "react";
import axios from "axios";
import toast, { Toaster } from "react-hot-toast";

export default function ParentFeePage() {
  const [admissionNo, setAdmissionNo] = useState("");
  const [summary, setSummary] = useState(null);
  const [overallFee, setOverallFee] = useState(null);

  // Fetch overall school fee structure for visitors
  useEffect(() => {
    const fetchOverall = async () => {
      try {
        const res = await axios.get("http://localhost:5000/api/fees");
        if (res.data.success) setOverallFee(res.data.data);
      } catch (err) { console.error(err); }
    };
    fetchOverall();
  }, []);

  // Fetch individual student's fee (if admission number provided)
  const fetchFee = async () => {
    if (!admissionNo.trim()) return toast.error("Please enter admission number");
    try {
      const res = await axios.get(`http://localhost:5000/api/fees/student/${admissionNo}`);
      if (res.data.success && res.data.data) {
        setSummary(res.data.data);
        toast.success("Fee record loaded!");
      } else {
        setSummary(null);
        toast.error("No record found!");
      }
    } catch (err) {
      console.error(err);
      toast.error("Failed to load fee structure");
    }
  };

  return (
    <div className="fee-page">
      <Toaster />
      <h2>💰 School Fee Structure</h2>

      {/* Overall fee for all visitors */}
      {overallFee && !summary && (
        <div className="fee-card">
          <h3>Fee Structure ({overallFee.academicYear})</h3>
          <div dangerouslySetInnerHTML={{ __html: overallFee.notes }} />
          <table className="fee-table">
            <thead>
              <tr>
                <th>Particulars</th>
                <th>Amount (₹)</th>
              </tr>
            </thead>
            <tbody>
              {overallFee.items.map((item) => (
                <tr key={item.key}>
                  <td>{item.title}</td>
                  <td>{item.amount}</td>
                </tr>
              ))}
              <tr className="fee-total">
                <td><b>Total</b></td>
                <td><b>₹{overallFee.items.reduce((sum, i) => sum + i.amount, 0)}</b></td>
              </tr>
            </tbody>
          </table>
          <p>Enter your Admission Number to view your individual fees and pay online.</p>
        </div>
      )}

      {/* Input for parents to fetch individual student fee */}
      <div className="search-box">
        <input
          type="text"
          value={admissionNo}
          onChange={(e) => setAdmissionNo(e.target.value)}
          placeholder="Enter Admission Number (e.g. KV-000000)"
        />
        <button onClick={fetchFee}>Search</button>
      </div>

      {/* Individual student fee */}
      {summary && (
        <div className="fee-card">
          <h3>{summary.student.studentName}'s Fee ({summary.fee.academicYear})</h3>
          <table className="fee-table">
            <thead>
              <tr>
                <th>Particulars</th>
                <th>Amount (₹)</th>
              </tr>
            </thead>
            <tbody>
              {Object.values(summary.fee.items).map((item) => (
                <tr key={item.title}>
                  <td>{item.title}</td>
                  <td>{item.amount}</td>
                </tr>
              ))}
              <tr className="fee-total">
                <td><b>Total</b></td>
                <td><b>₹{summary.fee.total}</b></td>
              </tr>
              <tr>
                <td>Paid</td>
                <td>₹{summary.fee.paid}</td>
              </tr>
              <tr>
                <td>Remaining</td>
                <td>₹{summary.fee.remaining}</td>
              </tr>
            </tbody>
          </table>
          {/* Pay button will appear here */}
        </div>
      )}
    </div>
  );
}























